{"command":"python3 -c '
import libtmux, time

deep_stack = ";".join([f"a{i}" for i in range(1, 35)]) + " 100\n"
with open("/tmp/deep.txt", "w") as f:
    f.write(deep_stack)

server = libtmux.Server()
if server.has_session("test_scroll"): server.kill_session("test_scroll")
session = server.new_session(session_name="test_scroll", window_name="win", width=80, height=24)
pane = session.active_pane
pane.send_keys("./executable /tmp/deep.txt", enter=True)
time.sleep(0.3)

def send(k):
    pane.send_keys(k, enter=False)
    time.sleep(0.1)

lines = pane.capture_pane()
print("Initial visible levels:")
for idx, l in enumerate(lines[3:18]):
    if l.strip(): print(f"Row {idx+3}: {repr(l)}")

send("f") # page down / scroll down
lines = pane.capture_pane()
print("\nAfter f (scroll down):")
for idx, l in enumerate(lines[3:18]):
    if l.strip(): print(f"Row {idx+3}: {repr(l)}")

send("G") # bottom
lines = pane.capture_pane()
print("\nAfter G (scroll to bottom):")
for idx, l in enumerate(lines[3:18]):
    if l.strip(): print(f"Row {idx+3}: {repr(l)}")

send("g") # top
lines = pane.capture_pane()
print("\nAfter g (scroll to top):")
for idx, l in enumerate(lines[3:18]):
    if l.strip(): print(f"Row {idx+3}: {repr(l)}")

session.kill()
'"}

