use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

fn hash_name<H: Hasher + Default>(name: &str) -> u64 {
    let mut hasher = H::default();
    name.hash(&mut hasher);
    hasher.finish()
}

fn main() {
    let names = ["alpha", "beta", "gamma", "delta", "epsilon", "zeta", "eta", "theta", "iota", "kappa", "main", "foo", "bar", "baz", "test", "run", "process", "handle", "compute", "parse"];
