use std::collections::hash_map::RandomState;
use std::hash::{BuildHasher, Hash, Hasher};

fn main() {
    let names = ["alpha", "beta", "gamma", "delta", "epsilon", "zeta", "eta", "theta", "iota", "kappa", "main", "foo", "bar", "baz", "test", "run", "process", "handle", "compute", "parse"];
    let obs_g = [121, 226, 95, 21, 53, 201, 91, 26, 2, 89, 219, 5, 69, 218, 206, 193, 71, 164, 191, 45];

    // Method 1: sum of bytes
    println!("=== Sum of bytes ===");
    for (i, name) in names.iter().enumerate() {
        let sum: u32 = name.bytes().map(|b| b as u32).sum();
        let g = (230.0 * (sum % 1000) as f64 / 1000.0) as u8;
        println!("{:<10}: obs={:<3} sum_mod={:<3}", name, obs_g[i], g);
    }

    // Method 2: FNV-1a
    println!("=== FNV-1a ===");
    for (i, name) in names.iter().enumerate() {
        let mut h: u32 = 2166136261;
        for b in name.bytes() {
            h ^= b as u32;
            h = h.wrapping_mul(16777619);
        }
        let v1 = (h as f64) / (u32::MAX as f64);
        let g1 = (230.0 * v1) as u8;
        let v2 = (h % 1000) as f64 / 1000.0;
        let g2 = (230.0 * v2) as u8;
        let g3 = (230.0 * (h as f64 / u32::MAX as f64)) as u8;
        println!("{:<10}: obs={:<3} fnv_div={:<3} fnv_mod={:<3}", name, obs_g[i], g1, g2);
    }
}
EOF

