import hashlib, struct

names = ["alpha", "beta", "gamma", "delta", "epsilon", "zeta", "eta", "theta", "iota", "kappa", "main", "foo", "bar", "baz", "test", "run", "process", "handle", "compute", "parse"]
obs_g = [121, 226, 95, 21, 53, 201, 91, 26, 2, 89, 219, 5, 69, 218, 206, 193, 71, 164, 191, 45]

# Let us test MD5 / SHA256 / SHA1 byte slices / uint32
for algo in ["md5", "sha1", "sha256"]:
    for offset in range(0, 16, 2):
        for mod in [230, 231, 256, 1000]:
            matches = 0
            for n, g in zip(names, obs_g):
                h = getattr(hashlib, algo)(n.encode()).digest()
                val = struct.unpack(">H", h[offset:offset+2])[0]
                if mod == 230: calc_g = val % 230
                else: calc_g = int(230.0 * (val % mod) / float(mod))
                if calc_g == g: matches += 1
            if matches > 10:
                print(f"ALGO {algo} offset {offset} mod {mod}: matches {matches}/20")
'"}

