{"command":"cat << 'EOF' > src/model.rs
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct Node {
    pub name: String,
    pub total_samples: u64,
    pub children: Vec<Node>,
    pub child_map: HashMap<String, usize>,
}

impl Node {
    pub fn new(name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            total_samples: 0,
            children: Vec::new(),
            child_map: HashMap::new(),
        }
    }

    pub fn insert_stack(&mut self, frames: &[&str], count: u64) {
        self.total_samples += count;
        if frames.is_empty() {
            return;
        }

        let first = frames[0];
        let idx = if let Some(&idx) = self.child_map.get(first) {
            idx
        } else {
            let new_node = Node::new(first);
            let idx = self.children.len();
            self.children.push(new_node);
            self.child_map.insert(first.to_string(), idx);
            idx
        };

        self.children[idx].insert_stack(&frames[1..], count);
    }

    pub fn sort_children(&mut self) {
        self.children.sort_by(|a, b| b.total_samples.cmp(&a.total_samples));
        self.child_map.clear();
        for (i, child) in self.children.iter().enumerate() {
            self.child_map.insert(child.name.clone(), i);
        }
        for child in &mut self.children {
            child.sort_children();
        }
    }

    pub fn max_depth(&self) -> usize {
        if self.children.is_empty() {
            0
        } else {
            1 + self.children.iter().map(|c| c.max_depth()).max().unwrap_or(0)
        }
    }
}

#[derive(Debug, Clone)]
pub struct FoldedStack {
    pub frames: Vec<String>,
    pub count: u64,
}

#[derive(Debug, Clone)]
pub struct TableRow {
    pub name: String,
    pub total_samples: u64,
    pub own_samples: u64,
}

pub fn parse_folded_stacks(raw_data: &str, sorted: bool) -> (Node, Vec<FoldedStack>, Vec<TableRow>) {
    let mut root = Node::new("all");
    let mut stacks = Vec::new();
    let mut total_map: HashMap<String, u64> = HashMap::new();
    let mut own_map: HashMap<String, u64> = HashMap::new();

    for line in raw_data.lines() {
        let line = line.trim_end_matches('\r');
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some((stack_str, count_str)) = line.rsplit_once(' ') {
            if let Ok(count) = count_str.parse::<u64>() {
                let frames: Vec<&str> = stack_str.split(';').collect();
                root.insert_stack(&frames, count);

                let string_frames: Vec<String> = frames.iter().map(|s| s.to_string()).collect();
                stacks.push(FoldedStack {
                    frames: string_frames.clone(),
                    count,
                });

                if let Some(leaf) = string_frames.last() {
                    *own_map.entry(leaf.clone()).or_insert(0) += count;
                }

                let mut seen_in_stack = HashMap::new();
                for frame in &string_frames {
                    if !seen_in_stack.contains_key(frame) {
                        seen_in_stack.insert(frame.clone(), true);
                        *total_map.entry(frame.clone()).or_insert(0) += count;
                    }
                }
            }
        }
    }

    if sorted {
        root.sort_children();
    }

    let mut table_rows: Vec<TableRow> = total_map
        .into_iter()
        .map(|(name, total_samples)| {
            let own_samples = own_map.get(&name).copied().unwrap_or(0);
            TableRow {
                name,
                total_samples,
                own_samples,
            }
        })
        .collect();

    // Default sort by own_samples descending
    table_rows.sort_by(|a, b| {
        b.own_samples
            .cmp(&a.own_samples)
            .then_with(|| b.total_samples.cmp(&a.total_samples))
            .then_with(|| a.name.cmp(&b.name))
    });

    (root, stacks, table_rows)
}

pub fn frame_color(name: &str) -> (u8, u8, u8) {
    let mut h: u32 = 2166136261;
    for b in name.bytes() {
        h ^= b as u32;
        h = h.wrapping_mul(16777619);
    }
    let v = ((h % 1000) as f32) / 1000.0;
    let r = (205.0 + 50.0 * v) as u8;
    let g = (230.0 * v) as u8;
    let b = (55.0 * v) as u8;
    (r, g, b)
}
EOF
"}

