{"command":"cat << 'EOF' > src/app.rs
use crate::model::{FoldedStack, Node, TableRow};
use regex::Regex;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ViewMode {
    Flamegraph,
    Table,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TableSortColumn {
    Own,
    Total,
}

pub struct App {
    pub filename_display: String,
    pub root: Node,
    pub stacks: Vec<FoldedStack>,
    pub table_rows: Vec<TableRow>,

    pub view_mode: ViewMode,
    pub table_sort: TableSortColumn,
    pub selected_table_index: usize,

    pub selected_path: Vec<usize>,
    pub zoomed_path: Vec<usize>,

    pub scroll_offset: usize,

    pub is_searching: bool,
    pub search_input: String,
    pub active_search_query: Option<String>,
    pub search_regex: Option<Regex>,
    pub regex_error: Option<String>,

    pub debug_enabled: bool,
    pub flamegraph_time_ms: f64,
    pub render_time_ms: f64,
}

impl App {
    pub fn new(
        filename_display: String,
        root: Node,
        stacks: Vec<FoldedStack>,
        table_rows: Vec<TableRow>,
        debug_enabled: bool,
    ) -> Self {
        Self {
            filename_display,
            root,
            stacks,
            table_rows,
            view_mode: ViewMode::Flamegraph,
            table_sort: TableSortColumn::Own,
            selected_table_index: 0,
            selected_path: Vec::new(),
            zoomed_path: Vec::new(),
            scroll_offset: 0,
            is_searching: false,
            search_input: String::new(),
            active_search_query: None,
            search_regex: None,
            regex_error: None,
            debug_enabled,
            flamegraph_time_ms: 0.02,
            render_time_ms: 0.01,
        }
    }

    pub fn get_node<'a>(&'a self, path: &[usize]) -> &'a Node {
        let mut curr = &self.root;
        for &idx in path {
            if idx < curr.children.len() {
                curr = &curr.children[idx];
            } else {
                break;
            }
        }
        curr
    }

    pub fn get_selected_node(&self) -> &Node {
        self.get_node(&self.selected_path)
    }

    pub fn get_zoomed_node(&self) -> &Node {
        self.get_node(&self.zoomed_path)
    }

    pub fn is_zoomed(&self) -> bool {
        !self.zoomed_path.is_empty()
    }

    pub fn sort_table(&mut self) {
        let sort_col = self.table_sort.clone();
        self.table_rows.sort_by(|a, b| match sort_col {
            TableSortColumn::Own => b
                .own_samples
                .cmp(&a.own_samples)
