        Self::collect_matches(&self.root, Vec::new(), re, &mut matches);

        if matches.is_empty() {
            return;
        }

        if forward {
            if let Some(pos) = matches.iter().position(|p| p == &self.selected_path) {
                if pos + 1 < matches.len() {
                    self.selected_path = matches[pos + 1].clone();
                } else {
                    self.selected_path = matches[matches.len() - 1].clone();
                }
            } else {
                // Find first match
                self.selected_path = matches[0].clone();
            }
        } else {
            if let Some(pos) = matches.iter().position(|p| p == &self.selected_path) {
                if pos > 0 {
                    self.selected_path = matches[pos - 1].clone();
                } else {
                    self.selected_path = matches[0].clone();
                }
            } else {
                self.selected_path = matches[0].clone();
            }
        }
        self.ensure_selected_visible();
    }

    fn collect_matches(node: &Node, path: Vec<usize>, re: &Regex, matches: &mut Vec<Vec<usize>>) {
        if re.is_match(&node.name) {
            matches.push(path.clone());
        }
        for (i, child) in node.children.iter().enumerate() {
            let mut child_path = path.clone();
            child_path.push(i);
            Self::collect_matches(child, child_path, re, matches);
        }
    }

    pub fn ensure_selected_visible(&mut self) {
        let depth = self.selected_path.len();
        if depth < self.scroll_offset {
            self.scroll_offset = depth;
        }
    }
}
