pub fn draw_ui(f: &mut Frame, app: &App) {
    let size = f.area();

    let mut constraints = vec![
        Constraint::Length(3), // Header
        Constraint::Min(0),    // Main area (Flamegraph or Table)
    ];

    if app.is_searching {
        constraints.push(Constraint::Length(2)); // Search bar
    } else if app.active_search_query.is_some() || app.regex_error.is_some() {
        constraints.push(Constraint::Length(2)); // Match / Info bar
    }

    constraints.push(Constraint::Length(2)); // Selected bar

    if app.debug_enabled {
        constraints.push(Constraint::Length(2)); // Debug bar
    }

    constraints.push(Constraint::Length(2)); // Help bar

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints(constraints)
        .split(size);

    let mut chunk_idx = 0;

    // 1. Header
    let header_chunk = chunks[chunk_idx];
    chunk_idx += 1;
    draw_header(f, app, header_chunk);

    // 2. Main Area
    let main_chunk = chunks[chunk_idx];
    chunk_idx += 1;
    match app.view_mode {
        ViewMode::Flamegraph => draw_flamegraph(f, app, main_chunk),
        ViewMode::Table => draw_table(f, app, main_chunk),
    }

    // 3. Search or Match/Info Bar
    if app.is_searching {
        let search_chunk = chunks[chunk_idx];
        chunk_idx += 1;
        draw_search_input(f, app, search_chunk);
    } else if app.active_search_query.is_some() || app.regex_error.is_some() {
        let match_chunk = chunks[chunk_idx];
        chunk_idx += 1;
        draw_match_info(f, app, match_chunk);
    }

    // 4. Selected Bar
    let selected_chunk = chunks[chunk_idx];
    chunk_idx += 1;
    draw_selected_info(f, app, selected_chunk);

    // 5. Debug Bar
    if app.debug_enabled {
        let debug_chunk = chunks[chunk_idx];
        chunk_idx += 1;
        draw_debug_info(f, app, debug_chunk);
    }

    // 6. Help Bar
    let help_chunk = chunks[chunk_idx];
    draw_help_bar(f, app, help_chunk);
}

fn draw_header(f: &mut Frame, app: &App, area: Rect) {
    let top_label = if app.is_zoomed() {
        app.get_zoomed_node().name.as_str()
    } else {
        "Top"
    };

    let (flame_part, top_part) = match app.view_mode {
        ViewMode::Flamegraph => (
            format!("[Flamegraph]"),
            format!(" | {}", top_label),
        ),
        ViewMode::Table => (
            format!("Flamegraph"),
            format!(" | [{}]", top_label),
        ),
    };

    let filename_part = &app.filename_display;
    let version_part = "flamelens v0.3.1";

    let left_spans = match app.view_mode {
        ViewMode::Flamegraph => vec![
            Span::raw(" "),
            Span::styled(
                "[Flamegraph]",
                Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD),
            ),
            Span::raw(" | "),
            Span::styled(top_label, Style::default().add_modifier(Modifier::BOLD)),
        ],
        ViewMode::Table => vec![
            Span::raw(" Flamegraph | "),
            Span::styled(
                format!("[{}]", top_label),
                Style::default().add_modifier(Modifier::BOLD),
            ),
        ],
    };

    let header_line_y = area.y + 1;
    let buf = f.buffer_mut();

    // Top border line
    for x in area.x..area.x + area.width {
        buf.get_mut(x, area.y)
            .set_symbol("─")
            .set_style(Style::default());
    }

    // Bottom border line
    for x in area.x..area.x + area.width {
        buf.get_mut(x, area.y + 2)
            .set_symbol("─")
            .set_style(Style::default());
    }

    // Header content row
    let mut x_pos = area.x;
    for span in left_spans {
        let text = span.content.as_ref();
        let style = span.style;
        for ch in text.chars() {
            if x_pos < area.x + area.width {
                buf.get_mut(x_pos, header_line_y)
                    .set_symbol(&ch.to_string())
                    .set_style(style);
                x_pos += 1;
            }
        }
    }

    // Center filename
    let center_x = area.x + (area.width.saturating_sub(filename_part.len() as u16)) / 2;
    if center_x > x_pos {
        let mut curr_x = center_x;
        for ch in filename_part.chars() {
            if curr_x < area.x + area.width {
                buf.get_mut(curr_x, header_line_y)
                    .set_symbol(&ch.to_string())
                    .set_style(Style::default().add_modifier(Modifier::BOLD));
                curr_x += 1;
