mod app;
mod args;
mod model;
mod ui;

use app::{App, TableSortColumn, ViewMode};
use args::parse_args;
use crossterm::{
    event::{self, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use model::parse_folded_stacks;
use ratatui::{backend::CrosstermBackend, Terminal};
use std::{
    error::Error,
    io::{self, Read, Write},
};

fn main() -> Result<(), Box<dyn Error>> {
    let args = parse_args();

    let filename_display = args
        .filename
        .as_deref()
        .unwrap_or("stdin")
        .to_string();

    let raw_data = match &args.filename {
        Some(path) => std::fs::read_to_string(path).expect("Could not read file"),
        None => {
            let mut buffer = String::new();
            io::stdin().read_to_string(&mut buffer)?;
            buffer
        }
    };

    if args.echo {
        println!("{}", raw_data);
    }

    let (root, stacks, table_rows) = parse_folded_stacks(&raw_data, args.sorted);

    let mut app = App::new(filename_display, root, stacks, table_rows, args.debug);

    // Setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let res = run_app(&mut terminal, &mut app);

    // Restore terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        eprintln!("{err:?}");
    }

    Ok(())
}

fn run_app<B: ratatui::backend::Backend>(
    terminal: &mut Terminal<B>,
    app: &mut App,
) -> io::Result<()> {
    loop {
        terminal.draw(|f| ui::draw_ui(f, app))?;

        if let Event::Key(key) = event::read()? {
            if app.is_searching {
                match key.code {
                    KeyCode::Char(c) => {
                        app.search_input.push(c);
                    }
                    KeyCode::Backspace => {
                        app.search_input.pop();
                    }
                    KeyCode::Enter => {
                        app.submit_search();
                    }
                    KeyCode::Esc => {
                        app.is_searching = false;
                        app.search_input.clear();
                    }
                    _ => {}
                }
            } else {
                if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('c') {
                    break;
                }

                match key.code {
                    KeyCode::Char('q') => {
                        break;
                    }
                    KeyCode::Tab => {
                        app.view_mode = match app.view_mode {
                            ViewMode::Flamegraph => ViewMode::Table,
                            ViewMode::Table => ViewMode::Flamegraph,
                        };
                    }
                    KeyCode::Char('r') => {
                        app.reset();
                    }
                    KeyCode::Char('/') => {
                        app.is_searching = true;
                        app.search_input.clear();
                    }
                    KeyCode::Char('#') => {
                        let name = match app.view_mode {
                            ViewMode::Flamegraph => app.get_selected_node().name.clone(),
                            ViewMode::Table => {
                                if let Some(row) = app.table_rows.get(app.selected_table_index) {
                                    row.name.clone()
                                } else {
                                    String::new()
                                }
                            }
                        };
                        if !name.is_empty() {
                            app.search_input = format!("^{}$", regex::escape(&name));
                            app.submit_search();
                        }
                    }
                    KeyCode::Char('n') => {
                        app.jump_match(true);
                    }
                    KeyCode::Char('N') => {
                        app.jump_match(false);
                    }

                    _ => match app.view_mode {
                        ViewMode::Flamegraph => handle_flamegraph_keys(app, key.code),
                        ViewMode::Table => handle_table_keys(app, key.code),
                    },
                }
            }
        }
    }

    Ok(())
}

fn handle_flamegraph_keys(app: &mut App, code: KeyCode) {
    let visible_height = 15; // default page scroll jump

    match code {
        KeyCode::Char('j') | KeyCode::Down => {
            let selected_node = app.get_selected_node();
            if !selected_node.children.is_empty() {
                // Move down to first child
                app.selected_path.push(0);
                app.ensure_selected_visible();
            }
        }
        KeyCode::Char('k') | KeyCode::Up => {
            if app.selected_path.len() > app.zoomed_path.len() {
                app.selected_path.pop();
                app.ensure_selected_visible();
            }
        }
        KeyCode::Char('h') | KeyCode::Left => {
            if app.selected_path.len() > app.zoomed_path.len() {
                if let Some(last) = app.selected_path.last_mut() {
                    if *last > 0 {
                        *last -= 1;
                    }
                }
            }
        }
        KeyCode::Char('l') | KeyCode::Right => {
            if app.selected_path.len() > app.zoomed_path.len() {
                let parent_path = &app.selected_path[..app.selected_path.len() - 1];
                let parent = app.get_node(parent_path);
                if let Some(last) = app.selected_path.last_mut() {
                    if *last + 1 < parent.children.len() {
                        *last += 1;
                    }
                }
            }
        }
        KeyCode::Enter => {
            app.zoomed_path = app.selected_path.clone();
            app.scroll_offset = 0;
        }
        KeyCode::Esc => {
            app.zoomed_path.clear();
            app.scroll_offset = 0;
        }
        KeyCode::Char('f') | KeyCode::PageDown => {
            app.scroll_offset += visible_height;
        }
        KeyCode::Char('b') | KeyCode::PageUp => {
            app.scroll_offset = app.scroll_offset.saturating_sub(visible_height);
        }
        KeyCode::Char('g') | KeyCode::Home => {
            app.scroll_offset = 0;
        }
        KeyCode::Char('G') | KeyCode::End => {
            let max_depth = app.get_zoomed_node().max_depth();
            app.scroll_offset = max_depth.saturating_sub(visible_height);
        }
        _ => {}
    }
}

fn handle_table_keys(app: &mut App, code: KeyCode) {
    match code {
        KeyCode::Char('j') | KeyCode::Down => {
            if !app.table_rows.is_empty() {
                app.selected_table_index = (app.selected_table_index + 1).min(app.table_rows.len() - 1);
            }
        }
        KeyCode::Char('k') | KeyCode::Up => {
            app.selected_table_index = app.selected_table_index.saturating_sub(1);
        }
        KeyCode::Char('1') => {
            app.table_sort = TableSortColumn::Total;
            app.sort_table();
        }
        KeyCode::Char('2') => {
            app.table_sort = TableSortColumn::Own;
            app.sort_table();
        }
        KeyCode::Enter => {
            if let Some(row) = app.table_rows.get(app.selected_table_index) {
                let name = row.name.clone();
                app.search_input = format!("^{}$", regex::escape(&name));
                app.submit_search();
                app.view_mode = ViewMode::Flamegraph;
            }
        }
        _ => {}
    }
}
