use crate::app::{App, TableSortColumn, ViewMode};
use crate::model::frame_color;
use ratatui::{
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::Span,
    Frame,
};

pub fn draw_ui(f: &mut Frame, app: &App) {
    let size = f.area();

    let mut constraints = vec![
        Constraint::Length(3), // Header
        Constraint::Min(0),    // Main area
    ];

    if app.is_searching {
        constraints.push(Constraint::Length(2)); // Search bar
    } else if app.active_search_query.is_some() || app.regex_error.is_some() {
        constraints.push(Constraint::Length(2)); // Match / Info bar
    }

    constraints.push(Constraint::Length(2)); // Selected bar

    if app.debug_enabled {
        constraints.push(Constraint::Length(2)); // Debug bar
    }

    constraints.push(Constraint::Length(2)); // Help bar

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints(constraints)
        .split(size);

    let mut chunk_idx = 0;

    // 1. Header
    let header_chunk = chunks[chunk_idx];
    chunk_idx += 1;
    draw_header(f, app, header_chunk);

    // 2. Main Area
    let main_chunk = chunks[chunk_idx];
    chunk_idx += 1;
    match app.view_mode {
        ViewMode::Flamegraph => draw_flamegraph(f, app, main_chunk),
        ViewMode::Table => draw_table(f, app, main_chunk),
    }

    // 3. Search or Match/Info Bar
    if app.is_searching {
        let search_chunk = chunks[chunk_idx];
        chunk_idx += 1;
        draw_search_input(f, app, search_chunk);
    } else if app.active_search_query.is_some() || app.regex_error.is_some() {
        let match_chunk = chunks[chunk_idx];
        chunk_idx += 1;
        draw_match_info(f, app, match_chunk);
    }

    // 4. Selected Bar
    let selected_chunk = chunks[chunk_idx];
    chunk_idx += 1;
    draw_selected_info(f, app, selected_chunk);

    // 5. Debug Bar
    if app.debug_enabled {
        let debug_chunk = chunks[chunk_idx];
        chunk_idx += 1;
        draw_debug_info(f, app, debug_chunk);
    }

    // 6. Help Bar
    let help_chunk = chunks[chunk_idx];
    draw_help_bar(f, app, help_chunk);
}

fn draw_header(f: &mut Frame, app: &App, area: Rect) {
    let top_label = if app.is_zoomed() {
        app.get_zoomed_node().name.as_str()
    } else {
        "Top"
    };

    let filename_part = &app.filename_display;
    let version_part = "flamelens v0.3.1";

    let left_spans = match app.view_mode {
        ViewMode::Flamegraph => vec![
            Span::raw(" "),
            Span::styled(
                "[Flamegraph]",
                Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD),
            ),
            Span::raw(" | "),
            Span::styled(top_label, Style::default().add_modifier(Modifier::BOLD)),
        ],
        ViewMode::Table => vec![
            Span::raw(" Flamegraph | "),
            Span::styled(
                format!("[{}]", top_label),
                Style::default().add_modifier(Modifier::BOLD),
            ),
        ],
    };

    let header_line_y = area.y + 1;
    let buf = f.buffer_mut();

    // Top border line
    for x in area.x..area.x + area.width {
        if let Some(cell) = buf.cell_mut((x, area.y)) {
            cell.set_symbol("─").set_style(Style::default());
        }
    }

    // Bottom border line
    for x in area.x..area.x + area.width {
        if let Some(cell) = buf.cell_mut((x, area.y + 2)) {
            cell.set_symbol("─").set_style(Style::default());
        }
    }

    // Header content row
    let mut x_pos = area.x;
    for span in left_spans {
        let text = span.content.as_ref();
        let style = span.style;
        for ch in text.chars() {
            if x_pos < area.x + area.width {
                if let Some(cell) = buf.cell_mut((x_pos, header_line_y)) {
                    cell.set_symbol(&ch.to_string()).set_style(style);
                }
                x_pos += 1;
            }
        }
    }

    // Center filename
    let center_x = area.x + (area.width.saturating_sub(filename_part.len() as u16)) / 2;
    if center_x > x_pos {
        let mut curr_x = center_x;
        for ch in filename_part.chars() {
            if curr_x < area.x + area.width {
                if let Some(cell) = buf.cell_mut((curr_x, header_line_y)) {
                    cell.set_symbol(&ch.to_string())
                        .set_style(Style::default().add_modifier(Modifier::BOLD));
                }
                curr_x += 1;
            }
        }
    }

    // Right version
    let right_x = area.x + area.width.saturating_sub(version_part.len() as u16);
    let mut curr_x = right_x;
    for ch in version_part.chars() {
        if curr_x < area.x + area.width {
            if let Some(cell) = buf.cell_mut((curr_x, header_line_y)) {
                cell.set_symbol(&ch.to_string())
                    .set_style(Style::default().add_modifier(Modifier::BOLD));
            }
            curr_x += 1;
        }
    }
}

fn draw_flamegraph(f: &mut Frame, app: &App, area: Rect) {
    let zoomed_node = app.get_zoomed_node();
    let total_zoomed_samples = zoomed_node.total_samples;
    if total_zoomed_samples == 0 || area.width == 0 || area.height == 0 {
        return;
    }

    let buf = f.buffer_mut();

    for row_idx in 0..area.height as usize {
        let depth = app.scroll_offset + row_idx;
        let y = area.y + row_idx as u16;

        let mut nodes_at_depth = Vec::new();
        collect_nodes_at_depth(
            zoomed_node,
            &app.zoomed_path,
            0,
            depth,
            0,
            &mut nodes_at_depth,
        );

        for (node_path, start_samples, node) in nodes_at_depth {
            let x1 = area.x
                + ((start_samples as f64 / total_zoomed_samples as f64) * area.width as f64)
                    .floor() as u16;
            let x2 = area.x
                + (((start_samples + node.total_samples) as f64 / total_zoomed_samples as f64)
                    * area.width as f64)
                    .floor() as u16;

            let bar_width = x2.saturating_sub(x1);
            if bar_width == 0 {
                continue;
            }

            let is_selected = node_path == app.selected_path;

            let is_matched = if let Some(re) = &app.search_regex {
                re.is_match(&node.name)
            } else {
                false
            };

            let bg_color = if is_selected {
                Color::Rgb(250, 250, 250)
            } else if is_matched {
                Color::Rgb(10, 35, 150)
            } else {
                let (r, g, b) = frame_color(&node.name);
                Color::Rgb(r, g, b)
            };

            let fg_color = if is_selected {
                Color::Rgb(10, 10, 10)
            } else if is_matched {
                Color::Rgb(225, 225, 225)
            } else {
                let (_, g, _) = frame_color(&node.name);
                if g > 100 {
                    Color::Rgb(10, 10, 10)
                } else {
                    Color::Rgb(225, 225, 225)
                }
            };

            // Fill background
            for x in x1..x2.min(area.x + area.width) {
                if let Some(cell) = buf.cell_mut((x, y)) {
                    cell.set_symbol(" ")
                        .set_style(Style::default().bg(bg_color).fg(fg_color));
                }
            }

            // Draw text
            let text_x = x1 + 1;
            let available_len = bar_width.saturating_sub(1) as usize;
            if available_len > 0 {
                let display_text = if node.name.len() > available_len {
                    &node.name[..available_len]
                } else {
                    &node.name
                };

                if is_matched && !is_selected {
                    if let Some(re) = &app.search_regex {
                        if let Some(mat) = re.find(display_text) {
                            let match_start = mat.start();
                            let match_end = mat.end();

                            let mut curr_x = text_x;
                            for (char_idx, ch) in display_text.chars().enumerate() {
                                if curr_x < area.x + area.width {
                                    let style = if char_idx >= match_start && char_idx < match_end {
                                        Style::default()
                                            .bg(bg_color)
                                            .fg(Color::Rgb(225, 10, 10))
                                            .add_modifier(Modifier::BOLD)
                                    } else {
                                        Style::default().bg(bg_color).fg(fg_color)
                                    };
                                    if let Some(cell) = buf.cell_mut((curr_x, y)) {
                                        cell.set_symbol(&ch.to_string()).set_style(style);
                                    }
                                    curr_x += 1;
                                }
                            }
                            continue;
                        }
                    }
                }

                let mut curr_x = text_x;
                for ch in display_text.chars() {
                    if curr_x < area.x + area.width {
                        if let Some(cell) = buf.cell_mut((curr_x, y)) {
                            cell.set_symbol(&ch.to_string())
                                .set_style(Style::default().bg(bg_color).fg(fg_color));
                        }
                        curr_x += 1;
                    }
                }
            }
        }
    }
}

fn collect_nodes_at_depth<'a>(
    node: &'a crate::model::Node,
    current_path: &[usize],
    current_depth: usize,
    target_depth: usize,
    start_samples: u64,
    results: &mut Vec<(Vec<usize>, u64, &'a crate::model::Node)>,
) {
    if current_depth == target_depth {
        results.push((current_path.to_vec(), start_samples, node));
        return;
    }

    let mut offset = start_samples;
    for (i, child) in node.children.iter().enumerate() {
        let mut child_path = current_path.to_vec();
        child_path.push(i);
        collect_nodes_at_depth(
            child,
            &child_path,
            current_depth + 1,
            target_depth,
            offset,
            results,
        );
        offset += child.total_samples;
    }
}

fn draw_table(f: &mut Frame, app: &App, area: Rect) {
    if area.width == 0 || area.height == 0 {
        return;
    }

    let root_total = app.root.total_samples;

    let mut max_total_len = 15;
    let mut max_own_len = 15;

    for row in &app.table_rows {
        let pct_total = if root_total > 0 {
            (row.total_samples as f64 / root_total as f64) * 100.0
        } else {
            0.0
        };
        let pct_own = if root_total > 0 {
            (row.own_samples as f64 / root_total as f64) * 100.0
        } else {
            0.0
        };

        let total_str = format!("{} ({:.2}%)", row.total_samples, pct_total);
        let own_str = format!("{} ({:.2}%)", row.own_samples, pct_own);

        if total_str.len() + 3 > max_total_len {
            max_total_len = total_str.len() + 3;
        }
        if own_str.len() + 3 > max_own_len {
            max_own_len = own_str.len() + 3;
        }
    }

    let total_hdr = if app.table_sort == TableSortColumn::Total {
        "Total [▼]"
    } else {
        "Total"
    };

    let own_hdr = if app.table_sort == TableSortColumn::Own {
        "Own [▼]"
    } else {
        "Own"
    };

    let header_line = format!(
        "{:<width1$}{:<width2$}Name",
        total_hdr,
        own_hdr,
        width1 = max_total_len,
        width2 = max_own_len
    );

    let buf = f.buffer_mut();

    let y = area.y;
    let mut x_pos = area.x;
    for ch in header_line.chars() {
        if x_pos < area.x + area.width {
            if let Some(cell) = buf.cell_mut((x_pos, y)) {
                cell.set_symbol(&ch.to_string()).set_style(Style::default());
            }
            x_pos += 1;
        }
    }

    for (i, row) in app.table_rows.iter().enumerate() {
        let row_y = area.y + 1 + i as u16;
        if row_y >= area.y + area.height {
            break;
        }

        let is_selected = i == app.selected_table_index;

        let pct_total = if root_total > 0 {
            (row.total_samples as f64 / root_total as f64) * 100.0
        } else {
            0.0
        };
        let pct_own = if root_total > 0 {
            (row.own_samples as f64 / root_total as f64) * 100.0
        } else {
            0.0
        };

        let total_str = format!("{} ({:.2}%)", row.total_samples, pct_total);
        let own_str = format!("{} ({:.2}%)", row.own_samples, pct_own);

        let row_line = format!(
            "{:<width1$}{:<width2$}{}",
            total_str,
            own_str,
            row.name,
            width1 = max_total_len,
            width2 = max_own_len
        );

        let style = if is_selected {
            Style::default().bg(Color::Rgb(250, 250, 250)).fg(Color::Rgb(10, 10, 10))
        } else {
            Style::default()
        };

        let mut x_pos = area.x;
        for ch in row_line.chars() {
            if x_pos < area.x + area.width {
                if let Some(cell) = buf.cell_mut((x_pos, row_y)) {
                    cell.set_symbol(&ch.to_string()).set_style(style);
                }
                x_pos += 1;
            }
        }
    }
}

fn draw_search_input(f: &mut Frame, app: &App, area: Rect) {
    let title_line = draw_title_line("Search", area.width as usize);
    let buf = f.buffer_mut();

    for x in area.x..area.x + area.width {
        let idx = (x - area.x) as usize;
        let symbol = title_line.chars().nth(idx).unwrap_or('─');
        let style = if idx < "Search ".len() {
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
        } else {
            Style::default()
        };
        if let Some(cell) = buf.cell_mut((x, area.y)) {
            cell.set_symbol(&symbol.to_string()).set_style(style);
        }
    }

    let content_y = area.y + 1;
    let input_str = &app.search_input;
    let mut x_pos = area.x;
    for ch in input_str.chars() {
        if x_pos < area.x + area.width {
            if let Some(cell) = buf.cell_mut((x_pos, content_y)) {
                cell.set_symbol(&ch.to_string()).set_style(Style::default());
            }
            x_pos += 1;
        }
    }

    if x_pos < area.x + area.width {
        f.set_cursor_position((x_pos, content_y));
    }
}

fn draw_match_info(f: &mut Frame, app: &App, area: Rect) {
    let buf = f.buffer_mut();

    if let Some(err_msg) = &app.regex_error {
        let title_line = draw_title_line("Info", area.width as usize);
        for x in area.x..area.x + area.width {
