        Span::styled("f/b", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw(": scroll] ["),
        Span::styled("enter/esc", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
